{
    "version": "0.2.0",
    "configurations": [
        {
            "type": "lldb",
            "request": "launch",
            "name": "Debug executable",
            "cargo": {
                "args": [
                    "build",
                    "--bin", // หรือ "--example" หรือ "--test"
                    "my_project", // ชื่อของ executable ที่จะดีบั๊ก
                    "--package",
                    "my_project" // ชื่อของ package (โดยทั่วไปคือชื่อโปรเจกต์)
                ],
                "filter": {
                    "kind": "executable"
                }
            },
            "args": [], // สำหรับส่ง arguments เข้าไปในโปรแกรมของคุณ
            "cwd": "${workspaceFolder}"
        }
    ]
}
